DATA_ITEM_TYPES = frozenset({"lakehouse", "warehouse", "semantic_model", "kql_database"})
NO_BADGE_TYPES = frozenset({"dashboard"})


def allowed_badges(item_type: str) -> set[str]:
    """Endorsement badges an item type can receive.

    Args:
        item_type: Fabric item type, such as "lakehouse" or "report".

    Returns:
        Allowed badge names.
    """
    if item_type in NO_BADGE_TYPES:
        return set()
    badges = {"promoted", "certified"}
    if item_type in DATA_ITEM_TYPES:
        badges.add("master_data")
    return badges
